from pathlib import Path
from html import escape
from textwrap import dedent
root = Path(__file__).parent
NAV = [('about.html','About'),('programs.html','Our Work'),('competition.html','2026 Competition'),('get-involved.html','Get Involved')]
def make_page(name,title,description,content):
    header=''.join(f'<a href="{href}"'+(' aria-current="page"' if name==href else '')+f'>{text}</a>' for href,text in NAV)
    markup=f'''<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="{escape(description,quote=True)}">
<meta name="theme-color" content="#102f39">
<meta name="robots" content="noindex,nofollow">
<meta property="og:type" content="website"><meta property="og:site_name" content="Youth and Masses Foundation"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:image" content="assets/img/social-preview.jpg"><meta name="twitter:card" content="summary_large_image">
<title>{escape(title)} | Youth and Masses Foundation</title>
<link rel="icon" href="assets/img/yamaf-mark.png" type="image/png"><link rel="stylesheet" href="assets/css/styles.css">
<script src="assets/js/site.js" defer></script>
</head><body>
<a class="skip" href="#main">Skip to content</a>
<div class="preview" role="status">Website preview · Organizational and event information is being confirmed before launch</div>
<header class="site-header"><div class="container nav-row"><a class="brand" href="index.html" aria-label="YaMaF home"><span class="brand-icon"><img src="assets/img/yamaf-mark.png" alt=""></span><span class="brand-text">Youth &amp; Masses <br>Foundation<small>Let’s Rise and Build</small></span></a><button class="menu-toggle" type="button" aria-controls="primary-nav" aria-expanded="false" data-menu-toggle>Menu</button><nav id="primary-nav" class="nav-links" aria-label="Main navigation">{header}<a class="nav-contact" href="contact.html"{' aria-current="page"' if name=='contact.html' else ''}>Contact YaMaF →</a></nav></div></header>
<main id="main">{content}</main>
<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="index.html"><span class="brand-icon"><img src="assets/img/yamaf-mark.png" alt=""></span><span class="brand-text">Youth &amp; Masses<br>Foundation<small>Let’s Rise and Build</small></span></a><p>Building confidence, critical thinking and civic participation among young people in Sierra Leone.</p><p class="small">This preview is for organizational review. No fundraising or event registration is being processed on this site.</p></div><div><h3>Explore</h3><a href="about.html">About</a><a href="programs.html">Our work</a><a href="competition.html">2026 competition</a><a href="get-involved.html">Get involved</a></div><div><h3>Connect</h3><a href="contact.html">Contact</a><a href="privacy.html">Privacy</a><p>Freetown, Sierra Leone</p></div></div><div class="footer-bottom"><span>© <span id="year">2026</span> Youth and Masses Foundation. All rights reserved.</span><span>Independent foundation · Website preview awaiting approval</span></div></div></footer>
</body></html>'''
    (root/name).write_text(markup,encoding='utf-8')

def pagehero(kicker,heading,sub):
    return f'<section class="page-hero"><div class="container"><span class="eyebrow">{kicker}</span><h1>{heading}</h1><p>{sub}</p></div></section>'

